// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 drugs, uint256 payment) internal {
        payment = bound(payment, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= payment);
        vm.assume(drugs == 0 || c.marketDrugs() != 0);
        uint256 mBefore;
        try c.marketDrugs() returns (uint256 __r) { mBefore = __r; } catch { return; }
        bool reverted;
        try c.seedMarket{value: payment}(drugs) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted != (mBefore == 0));
    }

    function testFuzz_run(uint256 drugs, uint256 payment) public {
        _run(drugs, payment);
    }

    receive() external payable {}
}
